//! 🪢️ Every nested effect retains the original allocation and Work recipients.
use super::*;
use crate::{OriginalWork,OriginalWorkAuthority,OriginalWorkRecipient,OriginalWorkQuote,OriginalWorkQuoteComplete,OriginalWorkPartialCheck,OriginalWorkPartialCheckComplete,OriginalSourceTurnIdentity};
struct Producer;
impl OriginalWorkRecipient for Producer{
 type Context<'a,'b>=() where 'b:'a;
 fn validate_context<'a,'b>(&self,_:&())->Result<(),ValueError> where 'b:'a{Ok(())}
 fn source_turn<'a,'b>(&self,_:&())->Option<OriginalSourceTurnIdentity> where 'b:'a{None}
 fn admits<'r,'a,'b>(&mut self,_:&mut (),quote:OriginalWorkQuote<'r>,_:u64,_:u64)->OriginalWorkQuoteComplete<'r> where 'b:'a{quote.complete(Ok(true))}
 fn settle_partial<'r,'a,'b>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{check.complete(Ok(()))}
 fn recover_partial<'r,'a,'b>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r> where 'b:'a{check.pending()}
}
#[test]
fn nested_effect_preserves_the_original_marker_and_rejects_widened_authority(){
 let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::fixture_text!("../../📦️effect/🧪️tests/cases.json")).unwrap();let parent:RetainedCloneGrant=serde_json::from_value(law["parent"].clone()).unwrap();
 for row in law["cases"].as_array().unwrap(){let mut authority=OriginalWorkAuthority::new(Producer);authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let mut action=None;let mut proof=None;let maximum=law["maximumWorkUnits"].as_u64().unwrap();assert_eq!(work.prepare_for_action(maximum,&mut action).unwrap(),Some(true));let mut actual=None;let pointer=std::ptr::from_mut(&mut actual);let admitted=row["admitted"].as_bool().unwrap();let mut performed=None;work.issue_performed_for_action(action,&mut performed).unwrap();{let mut effect=RetainedAllocationEffect::new(parent,maximum,&mut actual,performed.as_mut().unwrap());let grant=RetainedCloneGrant{maximum_capacity_bytes:row["capacity"].as_u64().unwrap()as usize,..parent};let result=effect.reborrow(grant,row["work"].as_u64().unwrap());assert_eq!(result.is_ok(),admitted);if let Ok(mut nested)=result{assert_eq!(std::ptr::from_mut(nested.actual()),pointer);*nested.actual()=Some(law["attemptBytes"].as_u64().unwrap()as usize);assert!(nested.performed(1).unwrap())}assert_eq!(*effect.actual(),admitted.then_some(law["attemptBytes"].as_u64().unwrap()as usize));}work.claim_performed_for_action(action,&mut performed).unwrap();
  if admitted{let mut partial_output=None;assert!(work.settle_partial_for_action_into(action,&mut partial_output).unwrap());let receipt=partial_output.take().unwrap();assert_eq!((receipt.delta(),receipt.total(),receipt.admitted(),receipt.source_refusal().is_none()),(1,1,true,true));assert!(work.commit_for_action(1,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}else{work.cancel_for_action(&mut action).unwrap()} }).unwrap();assert!(!authority.has_live_actions())}
}
#[test]
fn nested_effect_uses_only_the_actual_remaining_original_work(){let mut authority=OriginalWorkAuthority::new(Producer);authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut action,mut receipt,mut proof)=(None,None,None);assert_eq!(work.prepare_for_action(2,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let mut actual=None;{let grant=RetainedCloneGrant::default();let mut parent=RetainedAllocationEffect::new(grant,3,&mut actual,receipt.as_mut().unwrap());let boundary=parent.performed_boundary();assert_eq!(parent.remaining_work_units().unwrap(),2);std::hint::black_box(1u64.wrapping_add(1));assert!(parent.performed(1).unwrap());assert_eq!(parent.remaining_work_units().unwrap(),1);assert!(parent.reborrow(grant,2).is_err());{let mut child=parent.reborrow(grant,1).unwrap();assert_eq!(child.performed_since(boundary).unwrap(),1);assert_eq!(child.remaining_work_units().unwrap(),1);let child_boundary=child.performed_boundary();std::hint::black_box(2u64.wrapping_add(1));assert!(child.performed(1).unwrap());std::hint::black_box(3u64.wrapping_add(1));assert!(!child.performed(1).unwrap());assert!(child.remaining_work_units().is_err());assert_eq!(child.performed_work(),2);assert_eq!(child.performed_since(child_boundary).unwrap(),2)}assert_eq!(parent.performed_work(),3);assert_eq!(parent.performed_since(boundary).unwrap(),3)}work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial_output=None;assert!(work.settle_partial_for_action_into(action,&mut partial_output).unwrap());let outcome=partial_output.take().unwrap();assert_eq!((outcome.delta(),outcome.total(),outcome.admitted()),(3,3,false));assert!(!work.commit_for_action(3,action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}).unwrap();assert!(!authority.has_live_actions())}

#[test]
fn performed_boundary_rejects_a_different_original_receipt(){
 let mut first=OriginalWorkAuthority::new(Producer);let mut second=OriginalWorkAuthority::new(Producer);first.with_loan(&mut (),|a|second.with_loan(&mut (),|b|{let(mut a,mut b)=(a.reborrow(),b.reborrow());let(mut wa,mut wb)=(OriginalWork::empty(),OriginalWork::empty());wa.recipient=Some(&mut a);wb.recipient=Some(&mut b);let(mut aa,mut ab,mut ra,mut rb)=(None,None,None,None);assert_eq!(wa.prepare_for_action(1,&mut aa).unwrap(),Some(true));assert_eq!(wb.prepare_for_action(1,&mut ab).unwrap(),Some(true));wa.issue_performed_for_action(aa,&mut ra).unwrap();wb.issue_performed_for_action(ab,&mut rb).unwrap();let(mut ma,mut mb)=(None,None);{let ea=RetainedAllocationEffect::new(Default::default(),1,&mut ma,ra.as_mut().unwrap());let eb=RetainedAllocationEffect::new(Default::default(),1,&mut mb,rb.as_mut().unwrap());assert!(eb.performed_since(ea.performed_boundary()).is_err())}wa.claim_performed_for_action(aa,&mut ra).unwrap();wb.claim_performed_for_action(ab,&mut rb).unwrap();wa.cancel_for_action(&mut aa).unwrap();wb.cancel_for_action(&mut ab).unwrap()}).unwrap()).unwrap();assert!(!first.has_live_actions()&&!second.has_live_actions())
}

#[test]
fn nested_effect_gets_exactly_the_live_remaining_work_where_the_whole_ceiling_is_rejected(){
 let law:serde_json::Value=serde_json::from_str(include_str!("work-nested.json")).unwrap();
 for row in law["cases"].as_array().unwrap(){
  let(parent,receipt,spent)=(row["parent"].as_u64().unwrap(),row["receipt"].as_u64().unwrap(),row["spent"].as_u64().unwrap());let label=row["label"].as_str().unwrap();
  let mut authority=OriginalWorkAuthority::new(Producer);
  authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut action,mut receipt_slot,mut proof)=(None,None,None);assert_eq!(work.prepare_for_action(receipt,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt_slot).unwrap();let mut actual=None;
   {let grant=RetainedCloneGrant::default();let mut effect=RetainedAllocationEffect::new(grant,parent,&mut actual,receipt_slot.as_mut().unwrap());if spent>0{effect.performed(spent).unwrap();}
    assert_eq!(effect.reborrow(grant,parent).is_ok(),row["wholeCeilingAdmitted"].as_bool().unwrap(),"{label}");
    let child=effect.nested(grant);assert_eq!(child.maximum_work_units(),row["nestedCeiling"].as_u64().unwrap(),"{label}");assert_eq!(child.performed_work(),0,"{label}");let ceiling=row["nestedCeiling"].as_u64().unwrap();assert_eq!(effect.nested_within(grant,1).maximum_work_units(),ceiling.min(1),"{label}");assert_eq!(effect.nested_within(grant,u64::MAX).maximum_work_units(),ceiling,"{label}")}
   work.claim_performed_for_action(action,&mut receipt_slot).unwrap();
   if spent==0{work.cancel_for_action(&mut action).unwrap()}else{let mut partial=None;work.settle_partial_for_action_into(action,&mut partial).unwrap();let outcome=partial.take().unwrap();if outcome.admitted(){assert!(work.commit_for_action(spent.into(),action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}else{assert!(!work.commit_for_action(spent.into(),action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap()}}
  }).unwrap();assert!(!authority.has_live_actions(),"{label}");
 }
 let grant=RetainedCloneGrant{maximum_items:4,maximum_depth:2,..Default::default()};let wide=RetainedCloneGrant{maximum_items:9,maximum_depth:7,..Default::default()};
 let mut authority=OriginalWorkAuthority::new(Producer);
 authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut action,mut receipt_slot)=(None,None);assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt_slot).unwrap();let mut actual=None;
  {let mut effect=RetainedAllocationEffect::new(grant,1,&mut actual,receipt_slot.as_mut().unwrap());let child=effect.nested(wide);assert_eq!(child.grant(),grant)}
  work.claim_performed_for_action(action,&mut receipt_slot).unwrap();work.cancel_for_action(&mut action).unwrap()
 }).unwrap();assert!(!authority.has_live_actions());
}
/// 🧵️ The same original action measures total Work through replaced receipts.
#[test]fn action_boundary_tracks_actual_work_across_receipts_and_rejects_foreign_action(){let law:serde_json::Value=serde_json::from_str(include_str!("action-boundary.json")).unwrap();let mut authority=OriginalWorkAuthority::new(Producer);authority.with_loan(&mut (),|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let(mut action,mut receipt,mut proof)=(None,None,None);assert_eq!(work.prepare_for_action(10,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();let mut actual=None;let(boundary,receipt_boundary);{let mut effect=RetainedAllocationEffect::new(Default::default(),10,&mut actual,receipt.as_mut().unwrap());boundary=effect.action_boundary();receipt_boundary=effect.performed_boundary();assert!(effect.performed(law["initial"].as_u64().unwrap()).unwrap());assert_eq!(effect.performed_since_action(boundary).unwrap(),u128::from(law["initial"].as_u64().unwrap()));}work.claim_performed_for_action(action,&mut receipt).unwrap();let mut partial=None;assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());drop(partial.take());work.issue_performed_for_action(action,&mut receipt).unwrap();{let mut effect=RetainedAllocationEffect::new(Default::default(),10,&mut actual,receipt.as_mut().unwrap());assert_eq!(effect.performed_since_action(boundary).unwrap(),u128::from(law["initial"].as_u64().unwrap()));assert_eq!(effect.performed_since(receipt_boundary).is_err(),law["receiptRejected"].as_bool().unwrap());assert!(effect.performed(law["later"].as_u64().unwrap()).unwrap());let total=effect.performed_since_action(boundary).unwrap();assert_eq!(total,u128::from(law["total"].as_u64().unwrap()));assert!(total>u128::from(law["selected"].as_u64().unwrap()));}work.claim_performed_for_action(action,&mut receipt).unwrap();assert!(work.settle_partial_for_action_into(action,&mut partial).unwrap());drop(partial.take());assert!(work.commit_for_action(u128::from(law["total"].as_u64().unwrap()),action,&mut proof).unwrap());work.finish_for_action(&mut proof,&mut action).unwrap();assert_eq!(work.prepare_for_action(1,&mut action).unwrap(),Some(true));work.issue_performed_for_action(action,&mut receipt).unwrap();{let effect=RetainedAllocationEffect::new(Default::default(),1,&mut actual,receipt.as_mut().unwrap());assert_eq!(effect.performed_since_action(boundary).is_err(),law["foreignRejected"].as_bool().unwrap())}work.claim_performed_for_action(action,&mut receipt).unwrap();work.cancel_for_action(&mut action).unwrap()}).unwrap();assert!(!authority.has_live_actions());}
